            ("いつごろの話？", "マーベル・スタジオ公式の年表の本によると、物語は『アントマン』の後に始まり、ストレンジの修行は『シビル・ウォー』と同じころ。最後の戦いは『ブラック・ウィドウ』より前の出来事です。"),
